76	 * Ensures `rg` is available, or throws.
77	 */
78	export async function ensureRgPath(): Promise<string> {
79	  const binPath = await getRipgrepPath();
80	  if (binPath !== null) {
81	    return binPath;
82	  }
83	  throw new Error(`Cannot find bundled ripgrep binary.`);
84	}
